
import { useEffect, useState } from "react";

const API_BASE_URL = 'http://localhost:3000/api';

export const useAnFireAPI = () => {
  const [data, setData] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const fetchAnime = async (options = {}) => {
    const { anime_slug, anime_link, force, update } = options;
    
    setLoading(true);
    setError(null);

    try {
      const params = {
        api_key: 'mysecretapikeyxd',
        ...(anime_slug && { anime_slug }),
        ...(anime_link && { anime_link }),
        ...(force && { force }),
        ...(update && { update })
      };

      const response = await axios.get(`${API_BASE_URL}/`, { params });
      console.log(response);
      
      setData(response.data);
      return response.data;
    } catch (err) {
      const errorMessage = err.response?.data?.error || 'Erro ao buscar dados do anime';
      setError(errorMessage);
      throw new Error(errorMessage);
    } finally {
      setLoading(false);
    }
  };

  return {
    data,
    loading,
    error,
    fetchAnime
  };
};

// Componente principal de pesquisa
const AnimeSearchComponent = () => {
  const [searchInput, setSearchInput] = useState('');
  const [searchType, setSearchType] = useState('slug'); // 'slug' ou 'link'
  const { data, loading, error, fetchAnime } = useAnFireAPI();

  const handleSearch = async (e) => {
    e.preventDefault();
    if (!searchInput.trim()) return;

    const searchParams = {};
    
    if (searchType === 'slug') {
      searchParams.anime_slug = searchInput.trim();
    } else {
      // Verifica se é um link válido
      if (searchInput.includes('animefire.plus')) {
        searchParams.anime_link = searchInput.trim();
      } else {
        alert('Por favor, insira um link válido do AnimeFire');
        return;
      }
    }

    try {
      await fetchAnime(searchParams);
    } catch (err) {
      console.error('Erro na busca:', err);
    }
  };

  const clearSearch = () => {
    setSearchInput('');
  };

  return (
    <div className="anime-search-container">
      <div className="search-header">
        <h1>Buscar Animes</h1>
        
        <form onSubmit={handleSearch} className="search-form">
          <div className="search-controls">
            <div className="input-group">
              <select 
                value={searchType}
                onChange={(e) => setSearchType(e.target.value)}
                className="search-type-select"
              >
                <option value="slug">Por Slug</option>
                <option value="link">Por Link</option>
              </select>
              
              <input
                type="text"
                value={searchInput}
                onChange={(e) => setSearchInput(e.target.value)}
                placeholder={
                  searchType === 'slug' 
                    ? 'Digite o slug do anime (ex: one-piece)...'
                    : 'Cole o link do AnimeFire...'
                }
                className="search-input"
              />
              
              <button 
                type="button" 
                onClick={clearSearch}
                className="clear-btn"
                disabled={!searchInput}
              >
                ×
              </button>
            </div>
            
            <button 
              type="submit" 
              disabled={loading || !searchInput.trim()}
              className="search-btn"
            >
              {loading ? 'Buscando...' : 'Buscar'}
            </button>
          </div>
        </form>
      </div>

      {/* Mensagens de Erro */}
      {error && (
        <div className="error-message">
          <strong>Erro:</strong> {error}
        </div>
      )}

      {/* Resultados */}
      <div className="search-results">
        {loading && (
          <div className="loading-spinner">
            <div className="spinner"></div>
            <p>Carregando dados do anime...</p>
          </div>
        )}

        {data && !data.error && (
          <AnimeDetails data={data} />
        )}

        {data && data.error && (
          <div className="error-message">
            <strong>Erro na API:</strong> {data.error}
          </div>
        )}
      </div>
    </div>
  );
};

// Componente para exibir os detalhes do anime
const AnimeDetails = ({ data }) => {
  return (
    <div className="anime-details">
      <div className="anime-header">
        <div className="anime-image">
          {data.anime_image && (
            <img src={data.anime_image} alt={data.anime_title} />
          )}
        </div>
        
        <div className="anime-info">
          <h2>{data.anime_title}</h2>
          {data.anime_title1 && <h3>{data.anime_title1}</h3>}
          
          <div className="anime-meta">
            {data.anime_score && (
              <div className="meta-item">
                <span className="label">Score:</span>
                <span className="value">{data.anime_score}</span>
              </div>
            )}
            
            {data.anime_votes && (
              <div className="meta-item">
                <span className="label">Votos:</span>
                <span className="value">{data.anime_votes}</span>
              </div>
            )}
          </div>

          {data.anime_info && (
            <div className="anime-tags">
              {data.anime_info.split(', ').map((tag, index) => (
                <span key={index} className="tag">{tag.trim()}</span>
              ))}
            </div>
          )}
        </div>
      </div>

      {data.anime_synopsis && (
        <div className="synopsis-section">
          <h4>Sinopse</h4>
          <p>{data.anime_synopsis}</p>
        </div>
      )}

      {data.youtube_trailer && (
        <div className="trailer-section">
          <h4>Trailer</h4>
          <div className="trailer-container">
            <iframe
              src={data.youtube_trailer}
              title="Trailer do anime"
              frameBorder="0"
              allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
              allowFullScreen
            />
          </div>
        </div>
      )}

      {data.episodes && data.episodes.length > 0 && (
        <EpisodesList episodes={data.episodes} />
      )}
    </div>
  );
};

// Componente para listar episódios
const EpisodesList = ({ episodes }) => {
  const [visibleEpisodes, setVisibleEpisodes] = useState(10);

  const loadMore = () => {
    setVisibleEpisodes(prev => prev + 10);
  };

  return (
    <div className="episodes-section">
      <h4>Episódios ({episodes.length})</h4>
      
      <div className="episodes-grid">
        {episodes.slice(0, visibleEpisodes).map((episode) => (
          <EpisodeCard key={episode.episode} episode={episode} />
        ))}
      </div>

      {visibleEpisodes < episodes.length && (
        <button onClick={loadMore} className="load-more-btn">
          Carregar Mais Episódios
        </button>
      )}
    </div>
  );
};

// Componente para cartão de episódio
const EpisodeCard = ({ episode }) => {
  const [showSources, setShowSources] = useState(false);

  const hasAvailableSources = episode.data && episode.data.some(source => source.status === 'ONLINE');

  return (
    <div className={`episode-card ${hasAvailableSources ? 'has-sources' : 'no-sources'}`}>
      <div 
        className="episode-header"
        onClick={() => setShowSources(!showSources)}
      >
        <h5>Episódio {episode.episode}</h5>
        <span className="episode-status">
          {hasAvailableSources ? 'Disponível' : 'Indisponível'}
        </span>
        <span className="toggle-icon">
          {showSources ? '▲' : '▼'}
        </span>
      </div>

      {showSources && episode.data && (
        <div className="sources-list">
          {episode.data.map((source, index) => (
            <div key={index} className={`source-item ${source.status.toLowerCase()}`}>
              <div className="source-info">
                <span className="resolution">{source.resolution}</span>
                <span className="status">{source.status}</span>
              </div>
              
              {source.url && source.status === 'ONLINE' && (
                <a 
                  href={source.url} 
                  target="_blank" 
                  rel="noopener noreferrer"
                  className="watch-btn"
                >
                  Assistir
                </a>
              )}
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

export default AnimeSearchComponent;